#[test]
fn nullable_function_pointer_is_one_pointer() {
    assert_eq!(size_of::<Option<ocgpuInitFn>>(), size_of::<usize>());
    assert_eq!(size_of::<Option<ocgpuCuInitFn>>(), size_of::<usize>());
    assert_eq!(size_of::<Option<ocgpuHipInitFn>>(), size_of::<usize>());
}

#[test]
fn abi_v1_pointer_width_is_64() {
    assert_eq!(usize::BITS, 64);
}

#[test]
fn target_c_long_layout_is_native() {
    #[cfg(target_os = "windows")]
    {
        assert_eq!(size_of::<core::ffi::c_long>(), 4);
        assert_eq!(size_of::<core::ffi::c_ulong>(), 4);
    }
    #[cfg(target_os = "linux")]
    {
        assert_eq!(size_of::<core::ffi::c_long>(), 8);
        assert_eq!(size_of::<core::ffi::c_ulong>(), 8);
    }
}
